export interface RecoveredMediaCounts {
  rejected: number;
  truncated: number;
}

function safeRecoveryCount(value: number | undefined): number {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(999, Math.max(0, Math.floor(value))) : 0;
}

export function formatRecoveredMediaStatus(status: RecoveredMediaStatus, language: LanguageCode, counts: Partial<RecoveredMediaCounts> = {}): string {
  const copy = RECOVERY_STATUS_COPY[language][status];
  const rejected = safeRecoveryCount(counts.rejected);
  const truncated = safeRecoveryCount(counts.truncated);
  const countCopy = RECOVERY_COUNT_COPY[language];
  const details = [rejected > 0 ? countCopy.skipped(rejected) : "", truncated > 0 ? countCopy.truncated(truncated) : ""].filter(Boolean);
  return details.length > 0 ? `${copy} ${details.join(" ")}` : copy;
}

export function formatRecoveredMediaSummary(summary: RecoveredMediaSummary, language: LanguageCode): string {
  return formatRecoveredMediaStatus(summary.status, language, { rejected: summary.rejectedCount, truncated: summary.truncatedCount });
}

export function formatRecoveredMediaAccessibilityAnnouncement(summary: RecoveredMediaSummary, language: LanguageCode): string {
  return summary.accessibilityLiveRegion === "polite" ? formatRecoveredMediaSummary(summary, language) : "";
}

