export function languageDirection(language: LanguageCode): "ltr" | "rtl" {
  return language === "ar" ? "rtl" : "ltr";
}

export function isLanguageCode(value: string | null): value is LanguageCode {
  return Boolean(value && supportedCodes.has(value as LanguageCode));
}

export function languageOption(code: LanguageCode): LanguageOption {
  return LANGUAGE_OPTIONS.find((option) => option.code === code) ?? LANGUAGE_OPTIONS[0];
}

export async function loadLanguage(): Promise<LanguageCode | null> {
  const value = await AsyncStorage.getItem(LANGUAGE_KEY);
  return isLanguageCode(value) ? value : null;
}

export async function saveLanguage(code: LanguageCode): Promise<void> {
  await AsyncStorage.setItem(LANGUAGE_KEY, code);
  const saved = await AsyncStorage.getItem(LANGUAGE_KEY);
  if (saved !== code) throw new Error("language_readback_mismatch");
}

export async function initializeLanguage(): Promise<LanguageCode> {
  if (!i18n.isInitialized) {
    await i18n.init({ resources: Object.fromEntries(LANGUAGE_OPTIONS.map((option) => [option.code, { translation: { ...ENGLISH_CORE_COPY, ...translatedCore[option.code], ...translatedRecovery[option.code], ...translatedScanRecovery[option.code] } }])), lng: "en", fallbackLng: "en", supportedLngs: LANGUAGE_OPTIONS.map((option) => option.code), interpolation: { escapeValue: false }, returnNull: false, react: { useSuspense: false } });
  }
  const saved = await loadLanguage().catch(() => null);
  const next = saved ?? "en";
  await i18n.changeLanguage(next);
  return next;
}

export { i18n };

