export function localizedAnalysisQualityReason(language: LanguageCode, reason?: AnalysisQualityReason): string | null {
  if (!reason) return null;
  return (ANALYSIS_QUALITY_REASON_COPY[language] ?? ANALYSIS_QUALITY_REASON_COPY.en)[reason];
}
